using System;using System.Collections.Generic;
namespace ManualDiceRoller {
public sealed class ModSettings {public bool SpellPools=true,EnemyRolls=true,Traps=true,Features=true;}
public static class Plugin {public static bool Enabled=true;public static ModSettings Settings=new ModSettings();public static bool Online;public static bool UnsupportedRulesMod{get{return false;}}public static bool Networked(){return Online;}public static bool Allows(RuleDefinitions.RollContext c){return true;}internal const RuleDefinitions.RollContext FeatureDice=(RuleDefinitions.RollContext)0x100,TrapDice=(RuleDefinitions.RollContext)0x200;public static void Log(string s){Console.WriteLine("LOG "+s);}public static void Warn(string s){Console.WriteLine("WARN "+s);}}
public sealed class RollPrompt {public readonly int[] Faces;public readonly string Title;public RollPrompt(string t,string a,string s,string n,int[] f){Faces=(int[])f.Clone();Title=t;}}
public static class RollWindow {public static bool Visible;public static readonly List<RollPrompt> Prompts=new List<RollPrompt>();public static readonly Queue<int[]> Inputs=new Queue<int[]>();public static bool CancelNext;static RollPrompt owned;public static void Display(RollPrompt p,Action<int[]> accept,Action cancel){Visible=true;owned=p;Prompts.Add(p);if(CancelNext){CancelNext=false;cancel();}else accept(Inputs.Dequeue());}public static void Close(RollPrompt p){if(ReferenceEquals(p,owned)){Visible=false;owned=null;}}public static void Close(){Visible=false;owned=null;}}
public static class RestPatches {public static bool CanConsumeNativeHitDie{get{return false;}}public static bool TryPrepare(NativeInvocation i,NativeRollPlan p){return false;}public static void Reset(){}}
public static class NativeAbilityPlanner {public static bool Previewing;public static bool AllowsStaticBonus;public static void Install(HarmonyLib.Harmony h){}public static bool TryPrepare(NativeInvocation i,NativeRollPlan p){return false;}}
public static class NativeSavePlanner {public static bool Previewing;public static bool AllowsStaticBonus;public static void Install(HarmonyLib.Harmony h){}public static bool TryPrepare(NativeInvocation i,NativeRollPlan p){return false;}}
}
